import tkinter as tk
from pathlib import Path
from datetime import datetime
from tkinter import messagebox

from ..models.model import Model
from ..views.view import View
from ..utils.build_fetcher import BuildFetcher, ThreadWithReturnValue
from ..utils.logger import logger, setup_logger
from ttkthemes import ThemedTk
from auto_config.generator import generator
from auto_config.generator.utils.utils import save_yaml_file


class Controller(ThemedTk):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, theme="adapta", **kwargs)

        self.withdraw()
        self.deiconify()
        self.title("ACG App")

        self.build_fetcher = BuildFetcher()
        self.model = Model()
        self.view = View(self, self.model)
        self.bind('<<GenerateConfig>>', lambda _: self.run_yaml_generator())

        self.view.grid(row=0, sticky=(tk.W + tk.E))
        self.resizable(0, 0)
        self.option_add('*Dialog.msg.font', 'Helvetica 11')
        self._output_path = ''
        setup_logger()

    def run(self):
        self.fetch_enb_builds()
        self.mainloop()

    def fetch_enb_builds(self):
        t = ThreadWithReturnValue(target=self.build_fetcher.get_builds)
        t.start()
        self.schedule_check_enb_builds(t)

    def run_yaml_generator(self):
        self.view.header_widgets_section.lock_generate_config()
        self.view.header_widgets_section.lock_validate_config()
        self.view.header_widgets_section.message.delete(0.0, tk.END)

        selected_profile = self.view.get_selected_profile()
        config = self.view.get_configuration()
        logger.info("Generating configuration")
        logger.debug(config)
        enb, ue, epc, env, build, fsm_type = self.model.run_yaml_generator(config, selected_profile)

        now = datetime.now()
        dt_string = now.strftime("%d_%m_%Y_%H:%M:%S")
        output_string = self.view.get_output_path()
        output_dir = Path(self.view.get_output_path()) / f"output_generator_{dt_string}"
        self._output_path = str(output_dir)
        output_yaml_dir = output_dir / "config"

        try:
            output_dir.mkdir(parents=True, exist_ok=True)
            output_yaml_dir.mkdir(parents=True, exist_ok=True)

            save_yaml_file(output_yaml_dir, 'enb.yaml', enb)
            save_yaml_file(output_yaml_dir, 'env.yaml', enb)
            save_yaml_file(output_yaml_dir, 'ue.yaml', ue)
            save_yaml_file(output_yaml_dir, 'epc.yaml', epc)
        except OSError:
            msg = f'Files cannot be created under {output_string}. Please, use path with write access.'
            messagebox.showerror(title='Generator', message=msg)
            logger.info(msg)
            self.view.header_widgets_section.unlock_validate_config()
            return

        t = ThreadWithReturnValue(target=generator.generate_config, kwargs={
            'device_type': fsm_type, 'build': build, 'output_dir': output_dir, 'custom_dir': output_yaml_dir,
            'log_path': output_dir, 'yaml_map': 'env=env.yaml,epc=epc.yaml,enb=enb.yaml,ue=ue.yaml',
            'profile': selected_profile})

        t.start()
        self.view.header_widgets_section.message.insert(0.0, "Generating config..")
        self.schedule_check_config_generated(t)

    def check_if_builds_fetched(self, t):
        if not t.is_alive():
            builds = t.join()
            widget = self.view.header_widgets_section.children['select_enb_build_combobox']
            if not builds:
                widget.set_items(["No connection to WFT, please try again later"])
                widget.set("WFT connection unavailable, try again later! :/")
                widget.config(state='disabled')
                msg = "WFT Unavailable, try again later!\nYou may now close the application"
                self.view.header_widgets_section.message.delete(0.0, tk.END)
                self.view.header_widgets_section.message.insert(0.0, msg)
                self.view.header_widgets_section.children['select_profile_combobox'].config(state='disabled')
                self.view.header_widgets_section.children['validate_config_button'].config(state='disabled')
                self.view.header_widgets_section.children['generate_config_button'].config(state='disabled')
                self.view.lock_whole_acg_view()
            widget.set_items(builds)
        else:
            self.schedule_check_enb_builds(t)

    def check_if_config_generated(self, t):
        if not t.is_alive():
            self.view.header_widgets_section.unlock_validate_config()
            result = t.join()
            if result:
                msg = 'Config files generated successfully'
                self.view.header_widgets_section.message.insert(tk.END, f'\n{msg}')
                response = messagebox.askyesno("Congratulations!", "Do you wish to open directory with generated files?")
                if response:
                    import subprocess
                    subprocess.Popen(["/usr/bin/pcmanfm", self._output_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                    # _output, _error = process.communicate()  # do not wait for process to
            else:
                msg = ('Generating config failed. Check logs:\n'
                       + f'{self._output_path}/generate_config.log\n'
                       + 'for further details and contact I_IHT_AUTOMATION@internal.nsn.com')
                msg_box = "Generating config failed :(                     Check logs for further details"
                self.view.header_widgets_section.message.insert(tk.END, f'\n{msg}')
                messagebox.showerror(title='Generator', message=msg_box)
        else:
            self.view.header_widgets_section.message.insert(tk.END, '.')
            self.schedule_check_config_generated(t)

    def schedule_check_config_generated(self, t):
        self.after(1000, self.check_if_config_generated, t)

    def schedule_check_enb_builds(self, t):
        self.after(1000, self.check_if_builds_fetched, t)


if __name__ == '__main__':
    acg_app = Controller()
    acg_app.run()
